do $$
declare u uuid:=gen_random_uuid(); sh uuid; c uuid:=gen_random_uuid(); pet uuid:=gen_random_uuid(); staff uuid:=gen_random_uuid(); s uuid:=gen_random_uuid(); extra uuid:=gen_random_uuid(); b uuid; hist uuid:=gen_random_uuid(); d date:=current_date+7; rejected boolean; tpl uuid:=gen_random_uuid(); pkg uuid:=gen_random_uuid(); req uuid:=gen_random_uuid(); n int; employee uuid:=gen_random_uuid(); own_booking uuid; legacy uuid; other_staff uuid:=gen_random_uuid();
begin
 insert into auth.users(id,email,raw_user_meta_data) values(u,'qa.second.'||u||'@example.com','{"role":"barber","segment":"pet","shop_name":"QA rollback"}');
 select id into sh from shops where owner_user_id=u;
 insert into barbers(id,shop_id,name) values(staff,sh,'QA');
 insert into barber_schedule(barber_id,day_of_week,is_active,start_time,end_time) select staff,day,true,'09:00','18:00' from generate_series(0,6) day;
 insert into shop_customers(id,shop_id,name,phone) values(c,sh,'QA','19999990000');
 insert into pets(id,shop_id,customer_id,name) values(pet,sh,c,'QA');
 insert into services(id,shop_id,name,price,duration_minutes) values(s,sh,'Banho',50,60),(extra,sh,'Extra',20,15);
 perform set_config('request.jwt.claim.sub',u::text,true);
 perform set_config('request.jwt.claims',json_build_object('sub',u,'role','authenticated')::text,true);
 insert into service_packages(id,shop_id,name,total_sessions,price,active) values(tpl,sh,'QA pacote',4,200,true);
 perform sell_customer_package(pkg,sh,tpl,c,pet,false,null);
 perform sell_customer_package(pkg,sh,tpl,c,pet,false,null);
 if (select sale_amount from customer_packages where id=pkg)<>200 or exists(select 1 from financial_transactions where customer_package_id=pkg) then raise exception 'FAIL pending sale';end if;
 perform receive_package_payment(pkg,80,'pix',req);perform receive_package_payment(pkg,80,'pix',req);
 if (select balance from package_balances(sh) where package_id=pkg)<>120 then raise exception 'FAIL package partial/idempotency';end if;
 perform receive_package_payment(pkg,120,'dinheiro',gen_random_uuid());
 perform record_historical_booking(hist,sh,staff,c,pet,current_date-2,'10:00',array[s],false,null,pkg,array[extra]);
 perform record_historical_booking(hist,sh,staff,c,pet,current_date-2,'10:00',array[s],false,null,pkg,array[extra]);
 if not exists(select 1 from bookings where id=hist and status='completed' and historical_entry and amount_due=20 and date=current_date-2 and (completed_at at time zone 'America/Sao_Paulo')::date=current_date-2 and created_at::date=current_date) then raise exception 'FAIL historical';end if;
 if (select used_sessions from customer_packages where id=pkg)<>1 then raise exception 'FAIL historical session duplicate';end if;
 perform receive_booking_payment(hist,20,'pix',gen_random_uuid());
 select count(*) into n from financial_transactions where booking_id=hist;
 perform manage_booking_archive(sh,array[hist],false);
 if (select status from bookings where id=hist)<>'completed' or (select count(*) from financial_transactions where booking_id=hist)<>n or (select count(*) from package_usages where booking_id=hist)<>1 then raise exception 'FAIL archive accounting';end if;
 perform manage_booking_archive(sh,array[hist],true);
 b:=create_operational_booking(sh,staff,c,pet,d,'10:00',array[s]);
 perform manage_booking_archive(sh,array[b],false);
 if exists(select 1 from public_booking_slots where shop_id=sh and date=d and time='10:00') then raise exception 'FAIL archived slot exposed';end if;
 perform create_operational_booking(sh,staff,c,pet,d,'10:00',array[s]);
 rejected:=false;begin perform manage_booking_archive(sh,array[b],true);exception when others then rejected:=true;end;
 if not rejected or (select archived_at from bookings where id=b) is null then raise exception 'FAIL restore conflict';end if;
 b:=create_operational_booking(sh,staff,c,pet,d,'14:00',array[s]);
 update services set duration_minutes=45 where id=s;
 perform refresh_booking_durations(sh,jsonb_build_array(jsonb_build_object('id',b,'before',60,'after',45,'date',d::text,'time','14:00:00','barber_id',staff)));
 if (select duration_minutes from bookings where id=b)<>45 then raise exception 'FAIL duration refresh';end if;
 legacy:=create_operational_booking(sh,staff,c,pet,d,'12:00',array[s]);
 perform create_operational_booking(sh,staff,c,pet,d,'12:45',array[s]);
 perform edit_operational_booking(legacy,array[s,extra],d,'12:00',NULL);
 if (select duration_minutes from bookings where id=legacy)<>45 then raise exception 'FAIL legacy edit expands reservation';end if;
 perform complete_booking(legacy,array[s,extra],'pix',70,NULL);
 perform complete_booking(legacy,array[s,extra],'pix',70,NULL);
 if (select count(*) from financial_transactions where booking_id=legacy)<>1 then raise exception 'FAIL legacy duplicate receipt';end if;
 -- Staff may complete assigned work, but cannot receive debts or manage archives.
 insert into auth.users(id,email,raw_user_meta_data) values(employee,'qa.staff.'||employee||'@example.com','{}');
 perform set_config('request.jwt.claims',json_build_object('sub',u,'role','service_role')::text,true);
 update barbers set user_id=employee where id=staff;
 perform set_config('request.jwt.claims',json_build_object('sub',u,'role','authenticated')::text,true);
 insert into barbers(id,shop_id,name) values(other_staff,sh,'QA outro');
 own_booking:=create_operational_booking(sh,staff,c,pet,d,'16:00',array[s]);
 perform set_config('request.jwt.claim.sub',employee::text,true);
 perform set_config('request.jwt.claims',json_build_object('sub',employee,'role','authenticated')::text,true);
 SET LOCAL ROLE authenticated;
 perform complete_booking_payment(own_booking,array[s],null,50,null,false,null,45);
 if (select status from bookings where id=own_booking)<>'completed' then raise exception 'FAIL staff completion';end if;
 rejected:=false;begin perform receive_booking_payment(own_booking,50,'pix',gen_random_uuid());exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL staff receipt permission';end if;
 rejected:=false;begin perform manage_booking_archive(sh,array[own_booking],false);exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL staff archive permission';end if;
 rejected:=false;begin perform receive_package_payment(pkg,1,'pix',gen_random_uuid());exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL staff package receipt';end if;
 rejected:=false;begin perform record_historical_booking(gen_random_uuid(),sh,other_staff,c,pet,current_date-1,'10:00',array[s],false);exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL staff other professional';end if;
 RESET ROLE;
 -- A failed batch leaves every earlier update unchanged.
 perform set_config('request.jwt.claim.sub',u::text,true);
 rejected:=false;begin perform refresh_booking_durations(sh,jsonb_build_array(jsonb_build_object('id',b,'before',45,'after',45,'date',d::text,'time','14:00:00','barber_id',staff),jsonb_build_object('id',hist,'before',60,'after',45,'date',(current_date-2)::text,'time','10:00:00','barber_id',staff)));exception when others then rejected:=true;end;
 if not rejected or (select duration_minutes from bookings where id=hist)<>60 then raise exception 'FAIL completed duration protection';end if;
 perform set_config('request.jwt.claim.sub',gen_random_uuid()::text,true);
 rejected:=false;begin perform manage_booking_archive(sh,array[b],false);exception when others then rejected:=true;end;
 if not rejected then raise exception 'FAIL unauthorized archive';end if;
end $$;
